async function getPost(id: string): Promise<Post> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`)
  if (!res.ok) {
    throw new Error(`Failed to fetch post ${id}`)
  }
  return (await res.json()) as Post
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`
  )
  if (!res.ok) {
    throw new Error(`Failed to fetch comments for post ${id}`)
  }
  return (await res.json()) as Comment[]
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params

  try {
    const post = await getPost(id)
    const description = post.body.substring(0, 160)

    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    notFound()
  }
}

export default async function Page({ params }: PageProps<'/blog/[id]'>) {
